blic @Null JsonValue get (String name) { JsonValue current = child; while (current != null && (current.name == null || !current.name.equals(name))) current = current.next; return current; } /** Returns the child with the specified name, ignoring case. * @return May be null. */ public @Null JsonValue getIgnoreCase (String name) { JsonValue current = child; while (current != null && (current.name == null || !current.name.equalsIgnoreCase(name))) current = current.next; return current; } /** Returns true if a child with the specified name exists. */ public boolean has (String name) { return get(name) != null; } /** Returns an iterator for the child with the specified name, or an empty iterator if no child is found. */ public JsonIterator iterator (String name) { JsonValue current = get(name); if (current == null) { JsonIterator iter = new JsonIterator(); iter.entry = null; return iter; } return current.iterator(); } /** Returns the child at the specified index. This requires walking the linked list to the specified entry, see * {@link JsonValue} for how to iterate efficiently. * @throws IllegalArgumentException if the child was not found. */ public JsonValue require (int index) { JsonValue current = get(index); if (current == null) throw new IllegalArgumentException("Child not found with index: " + index); return current; } /** Returns the child with the specified name. * @throws IllegalArgumentException if the child was not found. */ public JsonValue require (String name) { JsonValue current = get(name); if (current == null) throw new IllegalArgumentException("Child not found with name: " + name); return current; } /** Removes the child with the specified index. This requires walking the linked list to the specified entry, see * {@link JsonValue} for how to iterate efficiently. * @return May be null. */ public @Null JsonValue remove (int index) { JsonValue child = get(index); if (child == null) return null; if (last == child) last = child.prev; if (child.prev == null)