gValue != 0 ? "true" : "false"; break; case nullValue: v = null; break; default: throw new IllegalStateException("Value cannot be converted to string: " + value.type); } array[i] = v; } return array; } /** Returns the children of this value as a newly allocated float array. * @throws IllegalStateException if this is not an array. */ public float[] asFloatArray () { if (type != ValueType.array) throw new IllegalStateException("Value is not an array: " + type); float[] array = new float[size]; int i = 0; for (JsonValue value = child; value != null; value = value.next, i++) { float v; switch (value.type) { case stringValue: v = Float.parseFloat(value.stringValue); break; case doubleValue: v = (float)value.doubleValue; break; case longValue: v = value.longValue; break; case booleanValue: v = value.longValue != 0 ? 1 : 0; break; default: throw new IllegalStateException("Value cannot be converted to float: " + value.type); } array[i] = v; } return array; } /** Returns the children of this value as a newly allocated double array. * @throws IllegalStateException if this is not an array. */ public double[] asDoubleArray () { if (type != ValueType.array) throw new IllegalStateException("Value is not an array: " + type); double[] array = new double[size]; int i = 0; for (JsonValue value = child; value != null; value = value.next, i++) { double v; switch (value.type) { case stringValue: v = Double.parseDouble(value.stringValue); break; case doubleValue: v = value.doubleValue; break; case longValue: v = value.longValue; break; case booleanValue: v = value.longValue != 0 ? 1 : 0; break; default: throw new IllegalStateException("Value cannot be converted to double: " + value.type); } array[i] = v; } return array; } /** Returns the children of this value as a newly allocated long array. * @throws IllegalStateException if this is not an array. */ public long[] asLongArray () { if (type != ValueType.array) throw new IllegalStateException("Value is not an array: " + type); long[] array = new long[size]; int i = 0; for (JsonValue value = child; value != null; value = value.next, i++) { long v; switch (value.type) { case stringValue: v = Long.parseLong(value.stringValue); break; case doubleValue: v = (long)value.doubleValue; break; case longValue: v = value.longValue; break; case booleanValue: v = value.longValue != 0 ? 1 : 0; break; default: throw new IllegalStateException("Value cannot be converted to long: " + value.type); } array[i] = v; } return array; } /** Returns the children of this value as a newly allocated int array. * @throws IllegalStateException if this is not an array. */ public int[] asIntArray () { if (type != ValueType.array) throw new IllegalStateException("Value is not an array: " + type); int[] array = new int[size]; int i = 0; for (JsonValue value = child; value != null; value = value.next, i++) { int v; switch (value.type) { case stringValue: v = Integer.parseInt(value.stringValue); break; case doubleValue: v = (int)value.doubleValue; break; case longValue: v = (int)value.longValue; break; case booleanValue: v = value.longValue != 0 ? 1 : 0; break; default: throw new IllegalStateException("Value cannot be converted to int: " + value.type); } array[i] = v; } return array; } /** Returns the children of this value as a newly allocated boolean array. * @throws IllegalStateException if this is not an array. */ public boolean[] asBooleanArray () { if (type != ValueType.array) throw new IllegalStateException("Value is not an array: " + type); boolean[] array = new boolean[size]; int i = 0; for (JsonValue value = child; value != null; value = value.next, i++) { boolean v; switch (value.type) { case stringValue: v = Boolean.parseBoolean(value.stringValue); break; case doubleValue: v = value.doubleValue == 0; break; case longValue: v = value.longValue == 0; break; case booleanValue: v = value.longValue != 0; break; default: throw new IllegalStateException("Value cannot be converted to boolean: " + value.type); } array[i] = v; } retur