th() == 0 ? 0 : value.stringValue.charAt(0); break; case doubleValue: v = (char)value.doubleValue; break; case longValue: v = (char)value.longValue; break; case booleanValue: v = value.longValue != 0 ? '\u0001' : '\u0000'; break; default: throw new IllegalStateException("Value cannot be converted to char: " + value.type); } array[i] = v; } return array; } /** Returns true if a child with the specified name exists and has a child. */ public boolean hasChild (String name) { return getChild(name) != null; } /** Finds the child with the specified name and returns its first child. * @return May be null. */ public @Null JsonValue getChild (String name) { JsonValue child = get(name); return child == null ? null : child.child; } /** Finds the child with the specified name and returns it as a string. Returns defaultValue if not found. * @param defaultValue May be null. */ public String getString (String name, @Null String defaultValue) { JsonValue child = get(name); return (child == null || !child.isValue() || child.isNull()) ? defaultValue : child.asString(); } /** Finds the child with the specified name and returns it as a float. Returns defaultValue if not found. */ public float getFloat (String name, float defaultValue) { JsonValue child = get(name); return (child == null || !child.isValue() || child.isNull()) ? defaultValue : child.asFloat(); } /** Finds the child with the specified name and returns it as a double. Returns defaultValue if not found. */ public double getDouble (String name, double defaultValue) { JsonValue child = get(name); return (child == null || !child.isValue() || child.isNull()) ? defaultValue : child.asDouble(); } /** Finds the child with the specified name and returns it as a long. Returns defaultValue if not found. */ public long getLong (String name, long defaultValue) { JsonValue child = get(name); return (child == null || !child.isValue() || child.isNull()) ? defaultValue : child.asLong(); } /** Finds the child with the specified name and ret